window.N29_I18N = {"fr":{"meta.title":"Djason Nathiez — Développeur Unity Gameplay freelance | STUDIO N29","meta.description":"Portfolio de Djason Nathiez, développeur Unity freelance spécialisé en programmation gameplay, systèmes et réseau multijoueur. Projets : Discosmos, Beat Strike, Heroes Dawn, Delight.","meta.title.project":"{name} — Projet | Djason Nathiez, développeur Unity freelance","nav.projects":"Projets","nav.about":"À propos","nav.skills":"Compétences","nav.journey":"Parcours","nav.contact":"Contact","nav.cta":"Me contacter","nav.menu":"Menu","skip":"Aller au contenu","hero.status":"Disponible pour missions freelance","hero.l1":"Du gameplay","hero.l2":"qui se <span class=\"accent\">ressent.</span>","hero.role":"<strong>Djason Nathiez</strong> — Unity Gameplay Programmer","hero.lead":"Développeur Unity freelance spécialisé en gameplay, systèmes et réseau. Je transforme une intention de design en mécaniques solides, lisibles et agréables à jouer.","hero.cta1":"Voir les projets","hero.cta2":"Me contacter","hero.scroll":"Défiler","projects.eyebrow":"Projets","projects.title":"Ce que j'ai construit.","projects.lead":"Réseau, sorts, rythme, contrôleurs, systèmes de combat. Pour chaque projet : ce que j'ai réellement réalisé.","projects.view":"Voir le projet","status.wip":"En cours","status.nda":"NDA","p.discosmos.type":"MOBA 3D · 2 mois","p.discosmos.role":"Lead réseau & sorts","p.discosmos.desc":"Infrastructure réseau synchrone et architecture des sorts d'un MOBA 3D compétitif, réalisé en deux mois.","p.discosmos.tagline":"Un MOBA 3D réalisé en deux mois, où le netcode fait toute la différence.","p.discosmos.meta.role":"Lead réseau & sorts","p.discosmos.meta.team":"Projet d'équipe · 2 mois","p.discosmos.ctx":"Discosmos est un MOBA 3D compétitif réalisé en deux mois sous Unity avec Photon. J'y ai mis en place l'ensemble de l'infrastructure réseau synchrone et l'architecture des sorts, en visant la latence la plus faible possible pour que chaque partie reste juste et lisible.","p.discosmos.c1":"<strong>Netcode synchrone</strong> : connexion, salles, gestion des joueurs et synchronisation de l'état de jeu avec Photon.","p.discosmos.c2":"<strong>Latence</strong> : optimisation et compensation du lag pour garder des actions réactives entre joueurs.","p.discosmos.c3":"<strong>Système de sorts</strong> : architecture des compétences des personnages, lancement et application des effets, répliqués sur le réseau.","p.discosmos.c4":"<strong>Code extensible</strong> : structuré pour que l'équipe puisse ajouter des sorts sans retoucher à la couche réseau.","p.beat-strike.type":"Rythme mobile","p.beat-strike.role":"Moteur de rythme & outil d'éditeur","p.beat-strike.desc":"Moteur de rythme haute précision sur mobile, boucle de gameplay principale et outil Unity pour composer les patterns.","p.beat-strike.tagline":"Un jeu de rythme mobile où chaque coup se joue sur le tempo.","p.beat-strike.meta.role":"Core dev & tooling","p.beat-strike.meta.team":"Projet d'équipe","p.beat-strike.ctx":"Dans Beat Strike, le niveau défile, des ennemis apparaissent et le joueur enchaîne des interactions synchronisées sur le tempo pour attaquer et esquiver. J'ai développé le moteur rythmique, la boucle de gameplay principale et un outil Unity (Capacity Tool) pour composer les patterns en temps réel.","p.beat-strike.c1":"<strong>Moteur de rythme haute précision</strong>, pensé pour rester juste sur mobile.","p.beat-strike.c2":"<strong>Capacity Tool</strong> : un éditeur Unity avec timeline (BPM, durée, type d'interaction : attaque, esquive haute / basse…) utilisable par les designers sans toucher au code.","p.beat-strike.c3":"<strong>Patterns par BPM</strong> : bibliothèque de patterns d'attaque et de défense, sélectionnés selon le tempo du niveau.","p.beat-strike.c4":"<strong>Boucle de gameplay</strong> : enchaînement des tronçons de niveau, phases d'attaque et de défense, apparition des interactions et déclenchement des combats.","p.heroes-dawn.type":"RPG de gestion","p.heroes-dawn.role":"Conception & développement","p.heroes-dawn.desc":"RPG de gestion mobile-first dans un New York alternatif : exploration sur plateau, combat au tour par tour à timeline active et gestion de QG. Campagne de Brooklyn jouable (v0.9.0).","p.heroes-dawn.tagline":"Un RPG mobile où chaque tour se lit sur une timeline.","p.heroes-dawn.meta.role":"Conception & développement","p.heroes-dawn.meta.team":"Projet personnel","p.heroes-dawn.ctx":"Heroes Dawn est un RPG de gestion mobile-first dans l'Apex Universe, l'univers partagé des projets de Studio N29. Une escouade de méta-humains explore New York zone par zone : lancers de dé sur un plateau, combats au tour par tour sur une timeline active et gestion du QG entre les missions. La version actuelle (v0.9.0) propose une campagne de Brooklyn jouable en quatre zones.","p.heroes-dawn.c1":"<strong>Combat au tour par tour</strong> sur une timeline active, avec une synergie d'équipe qui remplace l'ancien système de combos.","p.heroes-dawn.c2":"<strong>Campagne de Brooklyn jouable</strong> : quatre zones (Red Hook, Brownsville, Coney Island, Dumbo et le pont) avec objectifs, ennemis et narration.","p.heroes-dawn.c3":"<strong>Onboarding et progression</strong> : première connexion (cinématique, pseudo narratif, campagne), suivi des quêtes du QG (principales et secondaires) et architecture de comptes prête pour Supabase.","p.heroes-dawn.c4":"<strong>Architecture propre</strong> : code en couches avec interface MVP, package de domaine en C# pur, VContainer, MessagePipe, UniTask et tests EditMode / PlayMode.","p.delight.type":"Aventure 3D","p.delight.role":"Gameplay Programmer","p.delight.desc":"Contrôleur de personnage 3D, IA ennemie par machines à états et architecture audio, sur un projet de groupe Rubika.","p.delight.tagline":"Une aventure 3D construite autour d'un contrôleur fluide et d'ennemis réactifs.","p.delight.meta.role":"Gameplay programming","p.delight.meta.team":"Projet de groupe (Rubika)","p.delight.ctx":"Delight est une aventure 3D réalisée en groupe à Rubika, aujourd'hui terminée. J'y ai architecturé les systèmes de jeu centraux : contrôleur de personnage, IA ennemie et audio. Une migration vers Unity 6 est en cours pour que le projet reste ouvrable et exploitable.","p.delight.c1":"<strong>Contrôleur de personnage 3D</strong> sur mesure, fluide et réactif.","p.delight.c2":"<strong>IA ennemie</strong> par machines à états (FSM), réactive au joueur.","p.delight.c3":"<strong>Architecture audio</strong> et intégration des sons dans le gameplay.","p.delight.c4":"<strong>Intégration des assets 3D</strong> dans les systèmes de jeu.","p.project-x.type":"Confidentiel","p.project-x.role":"Développement Unity","p.project-x.desc":"Un projet en cours de développement, sous accord de confidentialité. Les détails seront publiés après la levée du NDA.","p.project-x.tagline":"Un projet en cours, sous accord de confidentialité.","p.project-x.meta.role":"Développement Unity","p.project-x.meta.team":"Équipe","p.project-x.notice":"Ce projet est couvert par un accord de confidentialité. Je ne peux partager ni visuels, ni nom de client, ni détails techniques précis.","p.project-x.ctx":"Je contribue au développement d'un projet Unity mené en équipe. Ce que je peux en dire : il est en cours de production et je travaille dessus en tant que développeur Unity.","p.project-x.c1":"<strong>Développement de fonctionnalités</strong> en Unity et C#, au sein d'une équipe.","p.project-x.c2":"<strong>Confidentialité stricte</strong> : aucun contenu du projet n'est publié ici.","p.project-x.c3":"<strong>Échange privé possible</strong> : je peux en dire davantage dans le cadre d'une discussion de mission.","pg.back":"Tous les projets","pg.role":"Rôle","pg.engine":"Moteur","pg.team":"Contexte","pg.tech":"Technos","pg.context":"Le projet","pg.contrib":"Ma contribution","pg.next.title":"Un projet similaire ? Parlons-en.","pg.next.cta":"Me contacter","pg.more":"Autres projets","about.eyebrow":"À propos","about.title":"Développeur gameplay, formé à Rubika.","about.p1":"Je suis <strong>développeur Unity</strong>, spécialisé en <strong>programmation gameplay</strong>, systèmes et réseau. J'ai étudié à Rubika (Supinfogame) en Bachelor Programmation, et je travaille aujourd'hui en freelance sous la bannière de <strong>STUDIO N29</strong>.","about.p2":"J'aime les mécaniques qui se sentent bien entre les mains : un combat lisible, un sort qui répond au bon moment, un réseau qui ne se remarque pas. Mes expériences m'ont aussi donné des compétences full-stack web, en LLM / IA et en prompt engineering.","about.p3":"Je m'intègre vite à une équipe, je communique clairement et j'aime livrer du code que d'autres peuvent reprendre.","about.f1.l":"projets présentés","about.f2.l":"langage principal","about.f3.l":"Rubika · Bachelor Programmation","about.f4.n":"Freelance","about.f4.l":"ouvert aux missions","skills.eyebrow":"Compétences","skills.title":"Ce que je peux prendre en charge.","skills.1.t":"Gameplay programming","skills.1.d":"Mécaniques de jeu, combat, sorts et capacités, boucle de jeu, prise en main et game feel.","skills.2.t":"Réseau & multijoueur","skills.2.d":"Architecture réseau, synchronisation d'état, actions répliquées et cohérence entre joueurs.","skills.3.t":"Outils d'éditeur","skills.3.d":"Outils Unity pour les designers : éditeurs de patterns, inspecteurs personnalisés, workflows data-driven.","skills.4.t":"Architecture & systèmes","skills.4.d":"Managers, pooling, sérialisation et chargement de données : un code propre qui tient à l'échelle.","skills.5.t":"Full-stack & IA","skills.5.d":"API back-end, bases de données graphes, intégration de LLM et prompt engineering.","skills.6.t":"Outils & pipeline","skills.6.d":"Git, cloud, 3D (Blender, Unreal) et collaboration avec les équipes art et design.","journey.eyebrow":"Parcours","journey.title":"D'où je viens.","journey.1.date":"Juin 2026 → Janv. 2027","journey.1.t":"Fullstack Developer","journey.1.o":"IdentityOS","journey.1.d":"Création d'une API back-end basée sur l'IA et les bases de données graphes, et d'un jeu narratif sous Unity qui utilise cette API.","journey.2.date":"Août 2024 → Nov. 2025","journey.2.t":"Web Developer","journey.2.o":"Central Cars","journey.2.d":"Site vitrine de véhicules d'occasion avec interface administrateur, et mise en place des outils numériques (cloud, facturation, stock).","journey.3.date":"Mars → Mai 2024","journey.3.t":"Technicien IT","journey.3.o":"Simoldes Plasticos","journey.3.d":"Gestion du matériel hardware et software, et création d'une application de suivi des consommables par scan de QR code.","journey.4.date":"2019 → 2023","journey.4.t":"Bachelor Programmation","journey.4.o":"Rubika — Supinfogame","journey.4.d":"Formation à la programmation de jeux vidéo : gameplay, systèmes et réseau.","contact.eyebrow":"Contact","contact.title":"Un projet ? Parlons gameplay.","contact.lead":"Prototype, renfort d'équipe, système réseau, outil d'éditeur : décrivez-moi votre besoin et je reviens vers vous rapidement.","contact.email":"E-mail","contact.web":"Site","contact.where":"Localisation","contact.where.v":"Hauts-de-France · remote possible","form.name":"Nom","form.email":"E-mail","form.topic":"Votre besoin","form.topic.0":"Choisir…","form.topic.1":"Mission freelance","form.topic.2":"Collaboration / projet","form.topic.3":"Autre","form.message":"Message","form.send":"Envoyer le message","form.sending":"Envoi…","form.ok":"Message envoyé. Je vous réponds très vite.","form.err":"Échec de l'envoi. Écrivez-moi directement :","foot.nda":"Project X est soumis à un accord de confidentialité.","p.beat-strike.c5":"<strong>Performance</strong> : pool d'objets pour les interactions, afin d'éviter les allocations en pleine partie.","p.delight.c5":"<strong>Migration vers Unity 6</strong> (en cours) : montée de version, plugins incompatibles et pipeline de rendu.","p.sweet-courrier.type":"Twin stick coop","p.sweet-courrier.role":"Gameplay Engineer","p.sweet-courrier.desc":"Shooter arcade coopératif : physique arcade, inputs multijoueur local et game feel.","p.sweet-courrier.tagline":"Un shooter coopératif où tout se joue au feeling.","p.sweet-courrier.meta.role":"Gameplay engineering","p.sweet-courrier.meta.team":"Projet d'équipe","p.sweet-courrier.ctx":"Sweet Courrier est un shooter arcade coopératif en twin stick. Je me suis concentré sur le game feel : la réactivité des contrôles et la physique dynamique des interactions.","p.sweet-courrier.c1":"<strong>Inputs multijoueur local</strong> : gestion de plusieurs manettes et joueurs sur le même écran.","p.sweet-courrier.c2":"<strong>Physique arcade</strong> : interactions dynamiques et lisibles.","p.sweet-courrier.c3":"<strong>Game feel</strong> : contrôles réactifs, retours visuels et sensations de jeu.","pg.watch":"Voir la vidéo de gameplay","pg.zoom":"Agrandir","lb.close":"Fermer","lb.prev":"Précédent","lb.next":"Suivant","contact.linkedin":"LinkedIn","projects.featured":"Projet phare","nav.reviews":"Avis","p.heroes-dawn.c5":"<strong>Outils de design dans l'éditeur</strong> (fenêtres Unity) pour les objets, compétences, agents et la narration, export CSV pour les tableurs de conception, et outils d'équilibrage (import de tableur et simulateur).","p.heroes-dawn.c6":"<strong>Documentation de production</strong> : GDD, specs de game design, direction artistique, flows UI et roadmap (Early Access Steam, puis mobile) posés avant d'écrire le code.","reviews.eyebrow":"Avis","reviews.title":"Ce que disent mes clients.","reviews.rating":"5.0","reviews.count":"1 avis sur Malt","reviews.cta":"Voir mon profil Malt","reviews.date":"Avis publié le 16/10/2026","reviews.role":"Product Operations Lead, Chukker App LLC","reviews.quote":"Strong all-round contribution across. Djason delivered the first draft of the match simulation algorithms, integrated RP Vision from the GDD with solid stabilisation and performance gains, and set up a clean Unity architecture, Git workflow and documentation. Djason was a reliable partner in production meetings, helping scope and split tasks clearly. Highly recommended for Unity game development.","reviews.note":"Avis tel que publié sur Malt (en anglais).","contact.malt":"Malt","p.n29-hq.type":"Outil interne","p.n29-hq.role":"Conception & développement","p.n29-hq.desc":"L'outil privé avec lequel je gère mon activité freelance : projets, suivi du temps, devis et factures, synchronisation chiffrée.","p.n29-hq.tagline":"Le cockpit privé de mon activité freelance : projets, documents, suivi du temps et facturation dans une seule application installable.","p.n29-hq.meta.role":"Conception et développement","p.n29-hq.meta.team":"Solo, outil interne","p.n29-hq.ctx":"N29 HQ est l'application interne que j'ai conçue pour gérer STUDIO N29 au quotidien. C'est une application web installable (PWA), prioritairement locale, qui fonctionne hors ligne et sur mon téléphone, avec le même style que ce site. Les captures utilisent des données de démonstration fictives.","p.n29-hq.c1":"<strong>Projets et tâches</strong> : plusieurs projets, chacun avec son tableau kanban et ses documents Markdown mis en page visuellement (polices, tailles, styles, tableaux).","p.n29-hq.c2":"<strong>Suivi du temps</strong> : chronomètre et saisie au calendrier avec rapports sur une plage de dates, dans l'esprit de Toggl.","p.n29-hq.c3":"<strong>Devis et factures</strong> conformes aux obligations françaises : numérotation continue, documents émis chaînés par empreinte, avoirs, acomptes.","p.n29-hq.c4":"<strong>Synchronisation chiffrée de bout en bout</strong> : AES-GCM avec phrase secrète, stockée sur Supabase avec sécurité par ligne, fusion à trois voies entre appareils.","p.n29-hq.c5":"<strong>Outils de production</strong> : un générateur de prompts Apex amélioré pour l'illustration."},"en":{"meta.title":"Djason Nathiez — Freelance Unity Gameplay Developer | STUDIO N29","meta.description":"Portfolio of Djason Nathiez, freelance Unity developer specialised in gameplay programming, systems and multiplayer networking. Projects: Discosmos, Beat Strike, Heroes Dawn, Delight.","meta.title.project":"{name} — Project | Djason Nathiez, freelance Unity developer","nav.projects":"Projects","nav.about":"About","nav.skills":"Skills","nav.journey":"Journey","nav.contact":"Contact","nav.cta":"Get in touch","nav.menu":"Menu","skip":"Skip to content","hero.status":"Available for freelance missions","hero.l1":"Gameplay","hero.l2":"you can <span class=\"accent\">feel.</span>","hero.role":"<strong>Djason Nathiez</strong> — Unity Gameplay Programmer","hero.lead":"Freelance Unity developer specialised in gameplay, systems and networking. I turn a design intention into solid, readable mechanics that feel great to play.","hero.cta1":"See the projects","hero.cta2":"Get in touch","hero.scroll":"Scroll","projects.eyebrow":"Projects","projects.title":"What I've built.","projects.lead":"Networking, spells, rhythm, controllers, combat systems. For each project: what I actually did.","projects.view":"View project","status.wip":"In progress","status.nda":"NDA","p.discosmos.type":"3D MOBA · 2 months","p.discosmos.role":"Lead Network & Skills","p.discosmos.desc":"Synchronous network infrastructure and skill architecture for a competitive 3D MOBA built in two months.","p.discosmos.tagline":"A 3D MOBA built in two months, where netcode makes all the difference.","p.discosmos.meta.role":"Lead Network & Skills","p.discosmos.meta.team":"Team project · 2 months","p.discosmos.ctx":"Discosmos is a competitive 3D MOBA built in two months in Unity with Photon. I set up the entire synchronous network infrastructure and the skill architecture, aiming for the lowest possible latency so every match stays fair and readable.","p.discosmos.c1":"<strong>Synchronous netcode</strong>: connection, rooms, player management and game-state synchronisation with Photon.","p.discosmos.c2":"<strong>Latency</strong>: optimisation and lag compensation to keep actions responsive between players.","p.discosmos.c3":"<strong>Skill system</strong>: architecture of the characters' abilities, casting and applying effects, replicated over the network.","p.discosmos.c4":"<strong>Extensible code</strong>: structured so the team can add skills without touching the network layer.","p.beat-strike.type":"Mobile rhythm","p.beat-strike.role":"Rhythm engine & editor tool","p.beat-strike.desc":"High-precision mobile rhythm engine, main gameplay loop and a Unity tool to compose patterns.","p.beat-strike.tagline":"A mobile rhythm game where every strike is played on the beat.","p.beat-strike.meta.role":"Core dev & tooling","p.beat-strike.meta.team":"Team project","p.beat-strike.ctx":"In Beat Strike the level scrolls, enemies show up and the player chains tempo-synced interactions to attack and dodge. I developed the rhythm engine, the main gameplay loop and a Unity tool (Capacity Tool) to compose patterns in real time.","p.beat-strike.c1":"<strong>High-precision rhythm engine</strong>, designed to stay accurate on mobile.","p.beat-strike.c2":"<strong>Capacity Tool</strong>: a Unity editor with a timeline (BPM, duration, interaction type: attack, up / down dodge…) that designers can use without touching code.","p.beat-strike.c3":"<strong>Patterns per BPM</strong>: a library of attack and defence patterns, picked according to the level's tempo.","p.beat-strike.c4":"<strong>Gameplay loop</strong>: level chunk sequencing, attack and defence phases, interaction spawning and combat triggering.","p.heroes-dawn.type":"Management RPG","p.heroes-dawn.role":"Design & development","p.heroes-dawn.desc":"Mobile-first management RPG in an alternate New York: board exploration, turn-based combat on an active timeline and HQ management. Playable Brooklyn campaign (v0.9.0).","p.heroes-dawn.tagline":"A mobile RPG where every turn is read on a timeline.","p.heroes-dawn.meta.role":"Design & development","p.heroes-dawn.meta.team":"Personal project","p.heroes-dawn.ctx":"Heroes Dawn is a mobile-first management RPG set in the Apex Universe, the shared universe of Studio N29's projects. A squad of meta-humans explores New York zone by zone: rolling dice across a board, fighting turn-based battles on an active timeline and managing their HQ between missions. The current build (v0.9.0) offers a playable Brooklyn campaign in four zones.","p.heroes-dawn.c1":"<strong>Turn-based combat</strong> on an active timeline, with team synergy replacing the former combo system.","p.heroes-dawn.c2":"<strong>Playable Brooklyn campaign</strong>: four zones (Red Hook, Brownsville, Coney Island, Dumbo and the bridge) with objectives, enemies and narration.","p.heroes-dawn.c3":"<strong>Onboarding and progression</strong>: first-login flow (cinematic, narrative nickname, campaign), HQ quest tracking (main and side quests) and an account architecture ready for Supabase.","p.heroes-dawn.c4":"<strong>Clean architecture</strong>: layered code with an MVP interface, a pure-C# domain package, VContainer, MessagePipe, UniTask and EditMode / PlayMode tests.","p.delight.type":"3D adventure","p.delight.role":"Gameplay Programmer","p.delight.desc":"3D character controller, state-machine enemy AI and audio architecture, on a Rubika group project.","p.delight.tagline":"A 3D adventure built around a fluid controller and reactive enemies.","p.delight.meta.role":"Gameplay programming","p.delight.meta.team":"Group project (Rubika)","p.delight.ctx":"Delight is a 3D adventure made in a group at Rubika, now completed. I architected the core game systems: character controller, enemy AI and audio. A migration to Unity 6 is under way so the project stays openable and usable.","p.delight.c1":"<strong>Custom 3D character controller</strong>, fluid and responsive.","p.delight.c2":"<strong>Enemy AI</strong> driven by finite state machines (FSM), reactive to the player.","p.delight.c3":"<strong>Audio architecture</strong> and integration of sound into gameplay.","p.delight.c4":"<strong>3D asset integration</strong> into the game systems.","p.project-x.type":"Confidential","p.project-x.role":"Unity development","p.project-x.desc":"A project in development, under a non-disclosure agreement. Details will be published once the NDA is lifted.","p.project-x.tagline":"A project in progress, under a non-disclosure agreement.","p.project-x.meta.role":"Unity development","p.project-x.meta.team":"Team","p.project-x.notice":"This project is covered by a non-disclosure agreement. I can't share visuals, client names or precise technical details.","p.project-x.ctx":"I contribute to the development of a Unity project built by a team. What I can say: it is in production and I work on it as a Unity developer.","p.project-x.c1":"<strong>Feature development</strong> in Unity and C#, within a team.","p.project-x.c2":"<strong>Strict confidentiality</strong>: no project content is published here.","p.project-x.c3":"<strong>Private discussion possible</strong>: I can say more as part of a mission discussion.","pg.back":"All projects","pg.role":"Role","pg.engine":"Engine","pg.team":"Context","pg.tech":"Tech","pg.context":"The project","pg.contrib":"My contribution","pg.next.title":"A similar project? Let's talk.","pg.next.cta":"Get in touch","pg.more":"Other projects","about.eyebrow":"About","about.title":"Gameplay developer, trained at Rubika.","about.p1":"I'm a <strong>Unity developer</strong> specialised in <strong>gameplay programming</strong>, systems and networking. I studied at Rubika (Supinfogame) in the Programming Bachelor, and I now work as a freelancer under the <strong>STUDIO N29</strong> banner.","about.p2":"I like mechanics that feel good in the hands: readable combat, a spell that responds at the right moment, networking you never notice. My experience also gave me full-stack web, LLM / AI and prompt-engineering skills.","about.p3":"I fit into a team quickly, communicate clearly and like shipping code that others can pick up.","about.f1.l":"projects featured","about.f2.l":"main language","about.f3.l":"Rubika · Programming Bachelor","about.f4.n":"Freelance","about.f4.l":"open to missions","skills.eyebrow":"Skills","skills.title":"What I can take on.","skills.1.t":"Gameplay programming","skills.1.d":"Game mechanics, combat, spells and abilities, game loop, controls and game feel.","skills.2.t":"Networking & multiplayer","skills.2.d":"Network architecture, state synchronisation, replicated actions and consistency between players.","skills.3.t":"Editor tools","skills.3.d":"Unity tools for designers: pattern editors, custom inspectors, data-driven workflows.","skills.4.t":"Architecture & systems","skills.4.d":"Managers, pooling, serialisation and data loading: clean code that scales.","skills.5.t":"Full-stack & AI","skills.5.d":"Back-end APIs, graph databases, LLM integration and prompt engineering.","skills.6.t":"Tools & pipeline","skills.6.d":"Git, cloud, 3D (Blender, Unreal) and collaboration with art and design teams.","journey.eyebrow":"Journey","journey.title":"Where I come from.","journey.1.date":"Jun 2026 → Jan 2027","journey.1.t":"Fullstack Developer","journey.1.o":"IdentityOS","journey.1.d":"Built an AI-based back-end API on graph databases, and a narrative game in Unity that uses this API.","journey.2.date":"Aug 2024 → Nov 2025","journey.2.t":"Web Developer","journey.2.o":"Central Cars","journey.2.d":"Showcase website for used vehicles with an admin interface, and setup of the digital tools (cloud, invoicing, stock).","journey.3.date":"Mar → May 2024","journey.3.t":"IT Technician","journey.3.o":"Simoldes Plasticos","journey.3.d":"Hardware and software maintenance, and a consumables tracking app based on QR-code scanning.","journey.4.date":"2019 → 2023","journey.4.t":"Programming Bachelor","journey.4.o":"Rubika — Supinfogame","journey.4.d":"Video game programming studies: gameplay, systems and networking.","contact.eyebrow":"Contact","contact.title":"A project? Let's talk gameplay.","contact.lead":"Prototype, team reinforcement, networking system, editor tool: describe your need and I'll get back to you quickly.","contact.email":"Email","contact.web":"Website","contact.where":"Location","contact.where.v":"Hauts-de-France, France · remote friendly","form.name":"Name","form.email":"Email","form.topic":"Your need","form.topic.0":"Choose…","form.topic.1":"Freelance mission","form.topic.2":"Collaboration / project","form.topic.3":"Other","form.message":"Message","form.send":"Send message","form.sending":"Sending…","form.ok":"Message sent. I'll reply very soon.","form.err":"Sending failed. Please email me directly:","foot.nda":"Project X is under a non-disclosure agreement.","p.beat-strike.c5":"<strong>Performance</strong>: object pooling for interactions to avoid allocations during play.","p.delight.c5":"<strong>Unity 6 migration</strong> (ongoing): version upgrade, incompatible plugins and render pipeline.","p.sweet-courrier.type":"Twin stick co-op","p.sweet-courrier.role":"Gameplay Engineer","p.sweet-courrier.desc":"Cooperative arcade shooter: arcade physics, local multiplayer input and game feel.","p.sweet-courrier.tagline":"A cooperative shooter where everything comes down to feel.","p.sweet-courrier.meta.role":"Gameplay engineering","p.sweet-courrier.meta.team":"Team project","p.sweet-courrier.ctx":"Sweet Courrier is a cooperative twin-stick arcade shooter. I focused on game feel: control responsiveness and dynamic interaction physics.","p.sweet-courrier.c1":"<strong>Local multiplayer input</strong>: handling several controllers and players on the same screen.","p.sweet-courrier.c2":"<strong>Arcade physics</strong>: dynamic, readable interactions.","p.sweet-courrier.c3":"<strong>Game feel</strong>: responsive controls, visual feedback and play sensations.","pg.watch":"Watch the gameplay video","pg.zoom":"Enlarge","lb.close":"Close","lb.prev":"Previous","lb.next":"Next","contact.linkedin":"LinkedIn","projects.featured":"Featured project","nav.reviews":"Reviews","p.heroes-dawn.c5":"<strong>In-editor design tools</strong> (Unity windows) for items, skills, agents and narration, CSV export for design spreadsheets, and balancing tools (spreadsheet import and simulator).","p.heroes-dawn.c6":"<strong>Production documentation</strong>: GDD, game-design specs, art direction, UI flows and a roadmap (Steam Early Access, then mobile) laid out before writing code.","reviews.eyebrow":"Reviews","reviews.title":"What clients say.","reviews.rating":"5.0","reviews.count":"1 review on Malt","reviews.cta":"See my Malt profile","reviews.date":"Review posted on 16/10/2026","reviews.role":"Product Operations Lead, Chukker App LLC","reviews.quote":"Strong all-round contribution across. Djason delivered the first draft of the match simulation algorithms, integrated RP Vision from the GDD with solid stabilisation and performance gains, and set up a clean Unity architecture, Git workflow and documentation. Djason was a reliable partner in production meetings, helping scope and split tasks clearly. Highly recommended for Unity game development.","reviews.note":"Review shown as published on Malt.","contact.malt":"Malt","p.n29-hq.type":"Internal tool","p.n29-hq.role":"Designer & Developer","p.n29-hq.desc":"The private tool I run my freelance business with: projects, time tracking, quotes and invoices, encrypted sync.","p.n29-hq.tagline":"The private cockpit of my freelance business: projects, documents, time tracking and invoicing in one installable app.","p.n29-hq.meta.role":"Design & development","p.n29-hq.meta.team":"Solo, in-house tool","p.n29-hq.ctx":"N29 HQ is the internal app I built to run STUDIO N29 day to day. It is a local-first, installable web app (PWA) that works offline and on my phone, with the same look as this site. Screenshots use fictional demo data.","p.n29-hq.c1":"<strong>Projects and tasks</strong>: several projects, each with its own kanban board and Markdown documents edited visually (fonts, sizes, styles, tables).","p.n29-hq.c2":"<strong>Time tracking</strong>: timer and calendar entries with date-range reports, in the spirit of Toggl.","p.n29-hq.c3":"<strong>Quotes and invoices</strong> following French legal requirements: continuous numbering, hash-chained issued documents, credit notes, deposits.","p.n29-hq.c4":"<strong>End-to-end encrypted sync</strong>: AES-GCM with a passphrase, stored on Supabase with row-level security, 3-way merge across devices.","p.n29-hq.c5":"<strong>Production tools</strong>: an improved Apex prompt generator for illustration work."}};
